import * as T from './vendor/three.module.js';

// Metre-scale companion to the Blender room. Research evidence stays separate from decorative props.
const wood=0x624127,brass=0xb99b55,plaster=0x344c52,paper=0xd5cba8;
const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.8});
const box=(name,size,pos,color,parent)=>{const o=new T.Mesh(new T.BoxGeometry(...size),mat(color));o.name=name;o.position.set(...pos);parent.add(o);return o;};
const point=(x,y,z)=>new T.Vector3(x,y,z);
const visible=o=>{while(o){if(!o.visible)return false;o=o.parent;}return true;};
export class StudyRoom {
 constructor(world,handlers){
  this.handlers=handlers;this.world=world;this.root=new T.Group();world.add(this.root);this.shell=new T.Group();this.root.add(this.shell);this.root.visible=false;this.enabled=false;this.targets=[];this.tools=[];this.cards=[];this.pageIndex=0;this.hypothesis=0;this.checks={};this.notes={};this.sound=false;this.candleOn=true;this.loupe=false;this.measure=false;this.measurePoints=[];this.atlas=null;this.catalog=[];this.audioReady=false;this.mode="none";this.markers=[];this.markerColor=0;this.roomMode=0;this.roomNames=["Archiwum","Gabinet botaniczny","Sala diagramów"];
  this.ambience=typeof Audio==='undefined'?null:new Audio('audio/study-ambience.ogg');if(this.ambience){this.ambience.loop=true;this.ambience.volume=.12;}
  this.paperSound=typeof Audio==='undefined'?null:new Audio('audio/page-lift.ogg');if(this.paperSound)this.paperSound.volume=.25;
  // Same dimensions and furniture zones as the approved Blender layout, shifted so XR starts at the centre.
  box('Floor',[6,.2,5],[0,-.1,-.8],0x494740,this.shell);
  box('North wall',[6.4,3.2,.2],[0,1.6,-3.4],plaster,this.shell);
  box('West wall',[.2,3.2,5],[-3.1,1.6,-.8],plaster,this.shell);box('East wall',[.2,3.2,5],[3.1,1.6,-.8],plaster,this.shell);
  box('South left',[1.76,3.2,.2],[-2.12,1.6,1.8],plaster,this.shell);box('South right',[1.76,3.2,.2],[2.12,1.6,1.8],plaster,this.shell);box('South lintel',[2.48,.8,.2],[0,2.8,1.8],plaster,this.shell);box('Ceiling',[6.4,.2,5.4],[0,3.3,-.8],plaster,this.shell);
  box('Archive back',[3.3,2.45,.16],[0,1.65,-3.1],wood,this.shell);
  box('Codex plinth',[1.7,.86,.7],[0,.43,-2.07],wood,this.shell);
  this.book=new T.Group();this.book.position.set(0,1.02,-1.98);this.book.rotation.x=-.78;this.root.add(this.book);
  this.bookLeaves=[-1,1].map(side=>{const o=new T.Mesh(new T.PlaneGeometry(.73,.88),new T.MeshBasicMaterial({color:paper,side:T.DoubleSide}));o.position.x=side*.38;this.book.add(o);this.targets.push(o);return o;});
  this.pinBoards=[];for(const side of [-1,1]){const g=new T.Group();g.position.set(side*2.89,1.65,-1.38);g.rotation.y=side===-1?Math.PI/2:-Math.PI/2;this.root.add(g);box('Pinboard frame',[2.3,1.45,.13],[0,0,0],wood,g);const b=new T.Mesh(new T.PlaneGeometry(2.15,1.3),new T.MeshBasicMaterial({color:0x193430,side:T.DoubleSide}));b.position.z=.075;b.userData.studyAction={kind:'pin',board:side===-1?'left':'right'};g.add(b);this.pinBoards.push(b);this.targets.push(b);}
  box('Tool table top',[1.25,.10,1],[2.2,.89,.24],wood,this.shell);for(const x of [1.69,2.71])for(const z of [-.16,.64])box('Table leg',[.08,.84,.08],[x,.42,z],wood,this.shell);
  this.candle=this.makeTool('candle',[2.55,.96,.08]);const tray=new T.Mesh(new T.CylinderGeometry(.13,.13,.035,24),mat(brass));this.candle.add(tray);const wax=new T.Mesh(new T.CylinderGeometry(.055,.055,.19,20),mat(paper));wax.position.y=.11;this.candle.add(wax);this.flame=new T.Mesh(new T.SphereGeometry(.023,10,8),new T.MeshBasicMaterial({color:0xffc36a}));this.flame.scale.y=2;this.flame.position.y=.235;this.candle.add(this.flame);this.candleLight=new T.PointLight(0xffbc64,.6,1.4,2);this.candleLight.position.y=.25;this.candle.add(this.candleLight);
  this.glass=this.makeTool('magnifier',[1.96,1.03,.1]);const rim=new T.Mesh(new T.TorusGeometry(.10,.012,8,32),mat(brass));this.glass.add(rim);box('Magnifier handle',[.03,.18,.03],[0,-.18,0],wood,this.glass);
  this.ruler=this.makeTool('ruler',[2.12,.98,.54]);box('Ruler',[.50,.035,.065],[0,0,0],brass,this.ruler);for(let i=0;i<11;i++)box('Tick',[.002,.002,.035],[-.25+i*.05,.019,0],0x191b16,this.ruler);
  this.overlay=this.makeTool('overlay',[1.8,1.05,.48]);box('Overlay border',[.32,.26,.018],[0,0,0],brass,this.overlay);this.overlaySheet=new T.Mesh(new T.PlaneGeometry(.29,.23),new T.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.5,side:T.DoubleSide}));this.overlaySheet.position.z=.012;this.overlay.add(this.overlaySheet);
  this.panel=this.makePanel(1024,1120,.86,.94);this.panel.mesh.position.set(-1.75,1.50,-.8);this.panel.mesh.rotation.y=1.0;this.panel.mesh.userData.studyAction={kind:'panel'};this.root.add(this.panel.mesh);this.targets.push(this.panel.mesh);
  this.zoomPanel=this.makePanel(800,800,.48,.48);this.zoomPanel.mesh.position.set(1.10,1.5,-1.1);this.root.add(this.zoomPanel.mesh);this.zoomPanel.mesh.visible=false;
  this.protractor=this.makeTool('protractor',[1.68,1.03,.06]);const arc=new T.Mesh(new T.TorusGeometry(.12,.008,8,48,Math.PI),mat(brass));this.protractor.add(arc);box('Protractor baseline',[.26,.012,.012],[0,0,0],brass,this.protractor);for(let i=0;i<=12;i++){const tick=box('Angle tick',[.002,.023,.008],[.112*Math.cos(i*Math.PI/12),.112*Math.sin(i*Math.PI/12),0],brass,this.protractor);tick.rotation.z=i*Math.PI/12-Math.PI/2;}
  this.extras=this.makePanel(1024,520,.94,.478);this.extras.mesh.position.set(0,2.23,-1.55);this.extras.mesh.userData.studyAction={kind:'extras'};this.root.add(this.extras.mesh);this.targets.push(this.extras.mesh);
  this.variants=[new T.Group(),new T.Group(),new T.Group()];this.variants.forEach(g=>this.shell.add(g));
  // Distinct furnishings share the approved room shell and the user's continuous workspace.
  for(let j=0;j<3;j++)for(let i=0;i<4;i++){box('Archive spine',[.075,.27,.22],[-2.72+i*.12,1.12+j*.37,-3.05],0x705444+j*0x080809,this.variants[0]);}for(let j=0;j<3;j++)box('Archive shelf',[.66,.035,.32],[-2.53, .96+j*.37,-3.02],wood,this.variants[0]);
  for(let i=0;i<4;i++){box('Specimen drawer',[.85,.22,.48],[-2.35,.18+i*.24,-2.87],0x476151,this.variants[1]);box('Drawer handle',[.2,.035,.04],[-2.35,.18+i*.24,-2.60],brass,this.variants[1]);}for(let i=0;i<3;i++){box('Empty specimen frame',[.52,.62,.035],[2.32,1.38+i*.68,-3.15],brass,this.variants[1]);box('Frame backing',[.47,.57,.04],[2.32,1.38+i*.68,-3.12],0xddd6b9,this.variants[1]);}
  for(const r of [.26,.43,.64]){const ring=new T.Mesh(new T.TorusGeometry(r,.009,6,64),mat(brass));ring.position.set(2.28,2.18,-3.18);this.variants[2].add(ring);}for(let i=0;i<12;i++){const a=i*Math.PI/6;const tick=box('Diagram dial',[.012,.08,.015],[2.28+.65*Math.sin(a),2.18+.65*Math.cos(a),-3.18],brass,this.variants[2]);tick.rotation.z=-a;}box('Diagram console',[.85,.9,.5],[-2.35,.45,-2.87],0x364459,this.variants[2]);
  this.setRoom(0,false);this.drawPanel();this.drawZoom(null,null);
 }
 makeTool(id,pos){const g=new T.Group();g.name=id;g.userData.studyTool=id;g.position.set(...pos);g.userData.homePosition=[...pos];this.root.add(g);this.tools.push(g);this.targets.push(g);return g;}
 makePanel(w,h,mw,mh){const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;return {canvas,ctx:canvas.getContext('2d'),texture,mesh:new T.Mesh(new T.PlaneGeometry(mw,mh),new T.MeshBasicMaterial({map:texture,side:T.DoubleSide})),areas:[]};}
 async init(atlas){this.atlas=atlas;this.catalog=atlas.pages;try{const r=await fetch('research/hypotheses.json');this.research=await r.json();if(!Array.isArray(this.research.hypotheses))throw Error('research');}catch{this.research={hypotheses:[]};this.handlers.say('Nie udało się pobrać checklisty. Modele nadal są dostępne.');}await this.showPages();this.drawPanel();}
 async showPages(){if(!this.atlas)return;const token=this.pageToken=(this.pageToken||0)+1;for(const c of this.cards){this.root.remove(c);c.geometry.dispose();c.material.map?.dispose();c.material.dispose();this.targets=this.targets.filter(x=>x!==c);}this.cards=[];const pages=this.catalog.slice(this.pageIndex,this.pageIndex+12);for(const [i,p] of pages.entries()){const ratio=p.width/p.height,height=Math.min(.48,.43/ratio),width=height*ratio;const card=new T.Mesh(new T.PlaneGeometry(width,height),new T.MeshBasicMaterial({color:paper,side:T.DoubleSide}));card.position.set(-1.36+(i%6)*.545,1.30+Math.floor(i/6)*.60,-2.999);card.userData.studyAction={kind:'page',scan:p.id};card.name='f'+p.label;this.root.add(card);this.cards.push(card);this.targets.push(card);new T.TextureLoader().loadAsync(`assets/thumbs/${p.id}.jpg`).then(t=>{if(token!==this.pageToken){t.dispose();return;}t.colorSpace=T.SRGBColorSpace;card.material.map=t;card.material.color.setHex(0xffffff);card.material.needsUpdate=true;}).catch(()=>{});}
  for(let i=0;i<2;i++){const leaf=this.bookLeaves[i],p=this.catalog[this.pageIndex+i];leaf.visible=!!p;leaf.material.map?.dispose();leaf.material.map=null;if(!p)continue;leaf.userData.studyAction={kind:'page',scan:p.id};leaf.scale.set(Math.min(1,(p.width/p.height)*.88/.73),Math.min(1,.73/(p.width/p.height)/.88),1);new T.TextureLoader().loadAsync(`assets/images/${p.id}.jpg`).then(t=>{if(token!==this.pageToken){t.dispose();return;}t.colorSpace=T.SRGBColorSpace;leaf.material.map=t;leaf.material.color.setHex(0xffffff);leaf.material.needsUpdate=true;}).catch(()=>{});}
  this.drawPanel();
 }
 filter(pages){this.catalog=pages;this.pageIndex=0;this.showPages();}
 nextPages(delta){const n=Math.ceil(this.catalog.length/12);this.pageIndex=((Math.floor(this.pageIndex/12)+delta+n)%n)*12;this.showPages();}
 setVisible(enabled,mr=false){this.enabled=enabled;this.root.visible=enabled;this.shell.visible=!mr;if(!enabled)this.ambience?.pause();else if(this.sound)this.ambience?.play().catch(()=>{});}
 playPaper(){if(!this.sound||!this.paperSound)return;this.paperSound.currentTime=0;this.paperSound.play().catch(()=>{});}
 toggleSound(){this.sound=!this.sound;if(this.sound&&this.enabled)this.ambience?.play().catch(()=>this.handlers.say('Dźwięk wymaga ponownego kliknięcia przycisku.'));else this.ambience?.pause();this.changed();}
 toggleCandle(){this.candleOn=!this.candleOn;this.flame.visible=this.candleLight.visible=this.candleOn;this.changed();}
 toggleLoupe(){this.loupe=!this.loupe;this.zoomPanel.mesh.visible=this.loupe;this.drawPanel();this.handlers.say(this.loupe?'Lupa: skieruj kontroler na model lub trzymaj lupę nad kartą.':'Lupa wyłączona.');}
 toolOf(o){while(o){if(o.userData.studyTool)return o;o=o.parent;}return null;}
 actionOf(o){while(o){if(o.userData.studyAction)return o.userData.studyAction;o=o.parent;}return null;}
 changed(){this.drawPanel();this.handlers.persist();}
 click(hit){const a=this.actionOf(hit.object);if(!a)return false;if(a.kind==='panel'||a.kind==='extras'){const panel=a.kind==='panel'?this.panel:this.extras;const x=hit.uv.x*panel.canvas.width,y=(1-hit.uv.y)*panel.canvas.height;panel.areas.find(a=>x>=a.x&&x<=a.x+a.w&&y>=a.y&&y<=a.y+a.h)?.action();}else if(a.kind==='pin'){this.handlers.pin(hit,a.board);}return true;}
 drawText(c,text,x,y,width,size=26,maxLines=3){c.font=`${size}px sans-serif`;let line='',row=0;for(const word of String(text).split(' ')){const test=line+word+' ';if(c.measureText(test).width>width&&line){c.fillText(line,x,y+row*32);line=word+' ';if(++row>=maxLines)return;}else line=test;}c.fillText(line,x,y+row*32);}
 drawPanel(){const {ctx:c,texture,areas}=this.panel;c.fillStyle='#101e27';c.fillRect(0,0,1024,1120);areas.length=0;c.fillStyle='#f4e8c7';c.font='bold 36px sans-serif';c.fillText('PRACOWNIA BADAWCZA',30,48);c.fillStyle='#c7d9dc';this.drawText(c,'Wyjmij kartę ze stojaka. Wskaż tablicę, aby przypiąć wybraną część.',30,88,964,26,2);
  const buttons=[['◀ Karty',()=>this.nextPages(-1)],['Karty ▶',()=>this.nextPages(1)],[this.loupe?'Lupa: WŁ.':'Lupa',()=>this.toggleLoupe()],['Odepnij',()=>this.handlers.unpin()],[this.candleOn?'Zgaś świecę':'Zapal świecę',()=>this.toggleCandle()],[this.sound?'Dźwięk: WŁ.':'Dźwięk: WYŁ.',()=>this.toggleSound()],['◀ Hipoteza',()=>{this.hypothesis=(this.hypothesis-1+(this.research?.hypotheses.length||1))%(this.research?.hypotheses.length||1);this.drawPanel();}],['Hipoteza ▶',()=>{this.hypothesis=(this.hypothesis+1)%(this.research?.hypotheses.length||1);this.drawPanel();}],['Otwórz źródło',()=>this.openSource()],['Pomiary punktów',()=>this.setMode('distance')],['Nakładka skanu',()=>this.handlers.overlay()],['Cofnij',()=>this.handlers.undo()]];
  const button=(label,action,x,y,w,h)=>{c.fillStyle='#294956';c.fillRect(x,y,w,h);c.fillStyle='#fff';c.font='26px sans-serif';c.fillText(label,x+13,y+43);areas.push({x,y,w,h,action});};buttons.forEach(([s,f],i)=>button(s,f,20+(i%3)*333,164+Math.floor(i/3)*74,317,64));
  const h=this.research?.hypotheses[this.hypothesis];c.fillStyle='#f2dfa5';if(h){this.onHypothesis?.(h);this.drawText(c,h.title,30,515,964,30,2);c.fillStyle='#afd6e2';this.drawText(c,h.status,30,585,964,24,2);h.checks.forEach((text,i)=>{const key=h.id+':'+i,y=665+i*67;c.fillStyle=this.checks[key]?'#90bf85':'#294956';c.fillRect(26,y-27,36,36);if(this.checks[key]){c.fillStyle='#142219';c.font='26px sans-serif';c.fillText('✓',29,y);}c.fillStyle='#eef3e6';this.drawText(c,text,80,y,910,22,2);areas.push({x:20,y:y-30,w:984,h:64,action:()=>{this.checks[key]=!this.checks[key];this.changed();}});});c.fillStyle='#d9c398';this.drawText(c,h.caution,30,1040,964,20,2);}else{c.fillStyle='#ddd';c.font='26px sans-serif';c.fillText('Wczytywanie źródeł checklisty…',30,520);}texture.needsUpdate=true;
 }
 async openSource(){const url=this.research?.hypotheses[this.hypothesis]?.source;if(!url){this.handlers.say('To Twoja hipoteza eksploracyjna; nie ma zewnętrznego źródła.');return;}await this.handlers.openURL(url);}
 drawZoom(image,uv,label='Lupa skanu'){const {ctx:c,texture}=this.zoomPanel;c.fillStyle='#101923';c.fillRect(0,0,800,800);c.fillStyle='#fff';c.font='26px sans-serif';c.fillText(label.slice(0,50),20,35);if(image?.width&&uv){const span=Math.max(48,Math.min(image.width,image.height)/4),sx=T.MathUtils.clamp(uv.x*image.width-span/2,0,image.width-span),sy=T.MathUtils.clamp((1-uv.y)*image.height-span/2,0,image.height-span);c.imageSmoothingEnabled=false;c.drawImage(image,sx,sy,span,span,45,60,710,710);}else c.fillText('Wskaż powierzchnię modelu.',20,95);texture.needsUpdate=true;}
 inspect(hit,now){if(!this.loupe||now-(this.lastZoom||0)<90)return;const material=hit?.object?.material,image=(Array.isArray(material)?material[0]:material)?.map?.image;if(!image||!hit.uv)return;this.lastZoom=now;this.drawZoom(image,hit.uv,'Lupa • tekstura źródłowa');}
 setMode(mode){this.mode=this.mode===mode?'none':mode;this.measure=this.mode==='distance'||this.mode==='angle';this.measurePoints=[];this.measureResult='';this.handlers.say(this.mode==='angle'?'Kąt w płaszczyźnie tekstury: wybierz A, wierzchołek B, punkt C na tej samej części.':this.mode==='mark'?'Znaczniki: wskaż punkt na modelu. Kolor zmienisz na panelu narzędzi.':this.mode==='distance'?'Odległość: wskaż dwa punkty tej samej tekstury.':'Wybieranie punktów wyłączone.');this.drawExtras();}
 activateTool(tool){if(tool===this.candle)this.toggleCandle();else if(tool===this.glass)this.toggleLoupe();else if(tool===this.overlay)this.handlers.overlay();else this.setMode(tool===this.protractor?'angle':'distance');}
 measureHit(hit,source){if(!this.measure||!hit.uv||!source)return false;const image=(Array.isArray(hit.object.material)?hit.object.material[0]:hit.object.material)?.map?.image;if(!image?.width||!image.height)return false;const p={source,x:hit.uv.x*image.width,y:(1-hit.uv.y)*image.height};const count=this.mode==='angle'?3:2;if(this.measurePoints.length===count)this.measurePoints=[];if(this.measurePoints[0]&&this.measurePoints[0].source!==source){this.handlers.say('Wybierz punkty na tej samej części źródłowej.');return true;}this.measurePoints.push(p);if(this.measurePoints.length===count){const [a,b,c]=this.measurePoints;if(count===3){const u=[a.x-b.x,a.y-b.y],v=[c.x-b.x,c.y-b.y],den=Math.hypot(...u)*Math.hypot(...v);this.measureResult=den<1e-8?'Punkty powtarzają się. Wybierz trzy różne punkty.':`Kąt ABC: ${(Math.acos(T.MathUtils.clamp((u[0]*v[0]+u[1]*v[1])/den,-1,1))*180/Math.PI).toFixed(1)}° · tekstura 2D`;}else this.measureResult=`Odległość: ${Math.hypot(b.x-a.x,b.y-a.y).toFixed(1)} px tekstury`;this.handlers.say(this.measureResult+' · '+source+'. Pomiar poglądowy; nie jest kalibracją oryginału.');}else this.handlers.say(`Punkt ${this.measurePoints.length}/${count} zapisany. Wskaż następny.`);this.drawExtras();return true;}
 markHit(hit,entry,piece){if(this.mode!=='mark'||!hit.uv||!piece)return false;if(this.markers.length>=100){this.handlers.say('Limit 100 znaczników. Usuń ostatni lub zapisz projekt.');return true;}this.handlers.remember?.();piece.updateWorldMatrix(true,false);const local=piece.worldToLocal(hit.point.clone()),image=(Array.isArray(hit.object.material)?hit.object.material[0]:hit.object.material)?.map?.image;this.createMarker({entryId:entry.id,pieceName:piece.name,scan:entry.scan,p:local.toArray(),uv:hit.uv.toArray(),textureSize:image?[image.width,image.height]:null,color:this.markerColor,label:this.markers.reduce((n,m)=>Math.max(n,m.record.label),0)+1});this.updateMarkers();this.changed();this.handlers.say('Znacznik '+this.markers.at(-1).record.label+' przypisany do części. Obraca się razem z nią.');return true;}
 createMarker(record){const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d');ctx.fillStyle=['#ffce68','#64daea','#ee99df'][record.color];ctx.fillRect(0,0,128,128);ctx.fillStyle='#14232b';ctx.font='bold 72px sans-serif';ctx.fillText(String(record.label),12,90);const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;const sprite=new T.Sprite(new T.SpriteMaterial({map:texture,depthTest:false}));sprite.scale.set(.028,.028,1);sprite.renderOrder=25;sprite.raycast=()=>{};this.root.add(sprite);this.markers.push({record,sprite});}
 clearMarkers(){for(const m of this.markers){this.root.remove(m.sprite);m.sprite.material.map.dispose();m.sprite.material.dispose();}this.markers=[];}
 removeMarker(){if(!this.markers.length)return;this.handlers.remember?.();const m=this.markers.pop();this.root.remove(m.sprite);m.sprite.material.map.dispose();m.sprite.material.dispose();this.changed();}
 updateMarkers(){for(const m of this.markers){const p=this.handlers.findPiece?.(m.record.entryId,m.record.pieceName);m.sprite.visible=!!p&&visible(p);if(p){p.updateWorldMatrix(true,false);m.sprite.position.copy(this.root.worldToLocal(p.localToWorld(new T.Vector3().fromArray(m.record.p))));}}}
 recallTools(){this.handlers.remember?.();this.handlers.release?.();const dock=this.handlers.toolDock?.()||{p:[0,1.08,-.62],yaw:0};this.tools.forEach((o,i)=>{this.root.attach(o);const p=new T.Vector3(-.5+i*.25,0,0).applyAxisAngle(new T.Vector3(0,1,0),dock.yaw).add(new T.Vector3().fromArray(dock.p));o.position.copy(this.root.worldToLocal(p));o.rotation.set(0,dock.yaw,0);});this.changed();this.handlers.say('Narzędzia przywołane przed Tobą. Chwyć przyciskiem bocznym.');}
 setRoom(index,save=true){this.roomMode=((index%3)+3)%3;this.variants?.forEach((g,i)=>g.visible=i===this.roomMode);const colors=[0x344c52,0x3e594d,0x343e5c];for(const o of this.shell.children)if(o.name.includes('wall')||o.name.includes('lintel'))o.material.color.setHex(colors[this.roomMode]);this.drawExtras();this.onRoom?.(this.roomMode);if(save){this.handlers.persist();this.handlers.say(this.roomNames[this.roomMode]+': ten sam układ modeli i znaczników, nowy wystrój.');}}
 drawExtras(){if(!this.extras)return;const {ctx:c,texture,areas}=this.extras;areas.length=0;c.fillStyle='#102430';c.fillRect(0,0,1024,520);c.fillStyle='#fff1c9';c.font='bold 34px sans-serif';c.fillText(this.roomNames[this.roomMode]+' · narzędzia',22,45);const actions=[['Miarka 2 pkt',()=>this.setMode('distance')],['Kąt A–B–C',()=>this.setMode('angle')],['Znaczniki',()=>this.setMode('mark')],['Kolor: '+['złoty','błękit','róż'][this.markerColor],()=>{this.markerColor=(this.markerColor+1)%3;this.drawExtras();}],['Usuń ostatni',()=>this.removeMarker()],['Zakończ pomiar',()=>{this.mode='none';this.measure=false;this.measurePoints=[];this.measureResult='';this.drawExtras();}],['Przywołaj narz.',()=>this.recallTools()],['◀ Pokój',()=>this.setRoom(this.roomMode-1)],['Pokój ▶',()=>this.setRoom(this.roomMode+1)]];actions.forEach(([label,action],i)=>{const x=18+(i%3)*335,y=76+Math.floor(i/3)*91;c.fillStyle='#315364';c.fillRect(x,y,320,80);c.fillStyle='#fff';c.font='27px sans-serif';c.fillText(label,x+12,y+49);areas.push({x,y,w:320,h:80,action});});c.fillStyle='#d6e7db';c.font='24px sans-serif';c.fillText('Tryb: '+({none:'chwytanie',angle:'kąt',distance:'odległość',mark:'znaczniki'}[this.mode]||'chwytanie')+' · Znaczniki: '+this.markers.length,22,392);this.drawText(c,this.measureResult||'Pokoje zachowują wspólne ułożenie modeli. Znaczniki są warstwą adnotacji.',22,433,970,24,2);texture.needsUpdate=true;}
 applyOverlay(piece){let source;piece?.traverse(o=>{if(!source&&o.isMesh)source=(Array.isArray(o.material)?o.material[0]:o.material)?.map;});if(!source){this.handlers.say('Wybierz część z teksturą skanu.');return;}this.overlaySheet.material.map?.dispose();this.overlaySheet.material.map=source.clone();this.overlaySheet.material.map.needsUpdate=true;this.overlaySheet.material.needsUpdate=true;const img=source.image,aspect=(img?.width||1)/(img?.height||1);this.overlaySheet.scale.set(Math.min(1,aspect*.23/.29),Math.min(1,.29/aspect/.23),1);this.handlers.say('Nakładka gotowa. Chwyć ramkę gripem i nałóż na inną kartę.');}
 capture(){return {roomMode:this.roomMode,markers:this.markers.map(m=>({...m.record,p:[...m.record.p],uv:[...m.record.uv]})),checks:{...this.checks},notes:{...this.notes},candleOn:this.candleOn,sound:this.sound,tools:this.tools.map(o=>{const p=new T.Vector3(),q=new T.Quaternion(),s=new T.Vector3();o.updateWorldMatrix(true,false);o.matrixWorld.decompose(p,q,s);this.root.worldToLocal(p);return {id:o.userData.studyTool,p:p.toArray(),q:q.toArray()};})};}
 restore(r){r=r||{};this.mode='none';this.measure=false;this.measurePoints=[];this.measureResult='';this.clearMarkers();for(const m of (Array.isArray(r.markers)?r.markers:[]).slice(0,100)){if(typeof m.entryId==='string'&&typeof m.pieceName==='string'&&Array.isArray(m.p)&&m.p.length===3&&m.p.every(Number.isFinite)&&Array.isArray(m.uv)&&m.uv.length===2&&m.uv.every(Number.isFinite)&&[0,1,2].includes(m.color)&&Number.isInteger(m.label)&&m.label>0&&m.label<=10000)this.createMarker({...m,p:[...m.p],uv:[...m.uv]});}this.setRoom(Number.isInteger(r.roomMode)?r.roomMode:0,false);this.updateMarkers();this.checks={};for(const [k,v] of Object.entries(r.checks||{}).slice(0,100))if(typeof v==='boolean')this.checks[k]=v;this.notes={};for(const [k,v] of Object.entries(r.notes||{}).slice(0,100))if(typeof v==='string')this.notes[k]=v.slice(0,2000);this.candleOn=r.candleOn!==false;this.flame.visible=this.candleLight.visible=this.candleOn;this.sound=r.sound===true;for(const t of (Array.isArray(r.tools)?r.tools:[])){const o=this.tools.find(o=>o.userData.studyTool===t.id);if(o&&Array.isArray(t.p)&&t.p.length===3&&t.p.every(Number.isFinite)&&Array.isArray(t.q)&&t.q.length===4&&t.q.every(Number.isFinite)){this.root.attach(o);o.position.fromArray(t.p);o.quaternion.fromArray(t.q).normalize();}}this.drawPanel();}
 update(time,hits){if(!this.enabled)return;this.updateMarkers();this.flame.scale.y=2+Math.sin(time*.008)*.12;this.candleLight.intensity=.6+Math.sin(time*.013)*.035;for(const hit of hits)if(hit)this.inspect(hit,time);}
 rayTargets(){return this.enabled?this.targets.filter(visible):[];}
}
